<div class="page-heading"><div><div class="eyebrow">Administrasi</div><h1>Akun petugas</h1><p>Kelola identitas dan peran petugas. Akun yang sudah memiliki riwayat kerja dinonaktifkan saat tidak digunakan.</p></div><button class="button primary" type="button" data-modal-open="add-staff">+ Tambah petugas</button></div>
<section class="card table-card"><div class="filter-results"><span><strong><?= (int)$pagination['total'] ?></strong> akun petugas</span></div><?php if ($staff): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Nama petugas</th><th>Email</th><th>Peran</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($staff as $person): $is_admin=in_array('administrator',explode(',',$person->role_codes),TRUE); ?><tr><td data-label="Nama"><strong><?= e($person->full_name) ?></strong></td><td data-label="Email"><?= email_html($person->email) ?></td><td data-label="Peran"><?= e($person->role_name) ?></td><td data-label="Status"><span class="badge <?= $person->account_status==='active'?'success':'danger' ?>"><?= $person->account_status==='active'?'Aktif':'Nonaktif' ?></span></td><td data-label="Aksi"><div class="row-actions"><?php if (!$is_admin || $this->metro->has_role($current_user->id,array('administrator'))): ?><button type="button" class="action-link" data-modal-open="edit-staff-<?= (int)$person->id ?>">Edit</button><?php endif; ?><?php if (!$is_admin && (int)$person->id!==(int)$current_user->id): ?><form method="post" action="<?= site_url('petugas/akun/status/'.$person->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="action-link" type="submit"><?= $person->account_status==='active'?'Nonaktifkan':'Aktifkan' ?></button></form><form method="post" action="<?= site_url('petugas/akun/hapus/'.$person->id) ?>" onsubmit="return confirm('Hapus akun yang belum memiliki riwayat kerja?')"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><button class="action-link danger" type="submit">Hapus</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="table-empty">Belum ada akun petugas.</div><?php endif; ?><?= metro_pager($pagination,'petugas/akun') ?></section>
<dialog id="add-staff" class="admin-modal" aria-labelledby="add-staff-title"><div class="modal-head"><div><small>Akses internal</small><h2 id="add-staff-title">Tambah petugas</h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/akun') ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="modal-body"><div class="form-grid"><label>Nama lengkap<input name="full_name" required minlength="3" maxlength="160"></label><label>Email<input type="email" name="email" required></label><label>Peran<select name="role_code" required><?php foreach ($staff_roles as $role): ?><option value="<?= e($role->role_code) ?>"><?= e($role->role_name) ?></option><?php endforeach; ?></select></label><label>Kata sandi awal<input type="password" name="password" minlength="8" maxlength="72" required autocomplete="new-password"></label></div><p class="muted small">Sampaikan kredensial awal melalui saluran internal yang aman.</p></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Buat akun</button></div></form></dialog>
<?php foreach ($staff as $person): $is_admin=in_array('administrator',explode(',',$person->role_codes),TRUE); if ($is_admin && !$this->metro->has_role($current_user->id,array('administrator'))) continue; ?><dialog id="edit-staff-<?= (int)$person->id ?>" class="admin-modal" aria-labelledby="edit-staff-title-<?= (int)$person->id ?>"><div class="modal-head"><div><small>Akun petugas</small><h2 id="edit-staff-title-<?= (int)$person->id ?>">Edit <?= e($person->full_name) ?></h2></div><button type="button" class="modal-close" data-modal-close aria-label="Tutup">×</button></div><form method="post" action="<?= site_url('petugas/akun/ubah/'.$person->id) ?>"><?= form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash()) ?><div class="modal-body"><div class="form-grid"><label>Nama lengkap<input name="full_name" required minlength="3" maxlength="160" value="<?= e($person->full_name) ?>"></label><label>Email<input type="email" name="email" required value="<?= e($person->email) ?>"></label><?php if ($is_admin): ?><label>Peran<input value="<?= e($person->role_name) ?>" disabled></label><?php else: ?><label>Peran<select name="role_code" required><?php foreach ($staff_roles as $role): ?><option value="<?= e($role->role_code) ?>"<?= in_array($role->role_code,explode(',',$person->role_codes),TRUE)?' selected':'' ?>><?= e($role->role_name) ?></option><?php endforeach; ?></select></label><?php endif; ?><label>Kata sandi baru <small>(opsional)</small><input type="password" name="password" minlength="8" maxlength="72" autocomplete="new-password" placeholder="Kosongkan bila tidak diubah"></label></div></div><div class="modal-actions"><button type="button" class="button outline" data-modal-close>Batal</button><button class="button primary" type="submit">Simpan perubahan</button></div></form></dialog><?php endforeach; ?>
